// Validation Helpers
// ============================================================
/**
 * Validates all fields in BootstrapConfig according to their annotations.
 * @throws {BlueErr} if validation fails
 */
export function validateBootstrapConfig(m: BootstrapConfig | undefined): void {
  if (!m) {
    return;
  }

  // Validate clusterName (assert_required)
  if (!m.clusterName) {
    throw newErrMissingInvalidData(undefined, `field clusterName is required`);
  }

  // Validate listener (assert_required)
  if (!m.listener) {
    throw newErrMissingInvalidData(undefined, `field listener is required`);
  }

  // Validate members (assert_required)
  if (!m.members) {
    throw newErrMissingInvalidData(undefined, `field members is required`);
  }

  // Validate members (assert_max_items: 32)
  if (m.members && m.members.length > 32) {
    throw newErrMissingInvalidData(
      undefined,
      `field members exceeds max items of 32, got: ${m.members.length}`,
    );
  }

  // Validate nodeCount (assert_gt: 0)
  if (m.nodeCount !== undefined && m.nodeCount <= 0) {
    throw newErrMissingInvalidData(
      undefined,
      `field nodeCount must be > 0, got: ${m.nodeCount}`,
    );
  }

  // Validate partitionCount (assert_gt: 0)
  if (m.partitionCount !== undefined && m.partitionCount <= 0) {
    throw newErrMissingInvalidData(
      undefined,
      `field partitionCount must be > 0, got: ${m.partitionCount}`,
    );
  }

  // Validate loaderCa (assert_max_items: 16)
  if (m.loaderCa && m.loaderCa.length > 16) {
    throw newErrMissingInvalidData(
      undefined,
      `field loaderCa exceeds max items of 16, got: ${m.loaderCa.length}`,
    );
  }

  // Validate tls (assert_required)
  if (!m.tls) {
    throw newErrMissingInvalidData(undefined, `field tls is required`);
  }

  // Validate clusterName (default max size: 32768 bytes)
  if (m.clusterName && new TextEncoder().encode(m.clusterName).length > 32768) {
    throw newErrMissingInvalidData(
      undefined,
      `field clusterName exceeds max size of 32768 bytes, got: ${new TextEncoder().encode(m.clusterName).length}`,
    );
  }

  // Validate secret (default max size: 32768 bytes)
  if (m.secret && new TextEncoder().encode(m.secret).length > 32768) {
    throw newErrMissingInvalidData(
      undefined,
      `field secret exceeds max size of 32768 bytes, got: ${new TextEncoder().encode(m.secret).length}`,
    );
  }

  // Validate persistenceDir (default max size: 32768 bytes)
  if (
    m.persistenceDir &&
    new TextEncoder().encode(m.persistenceDir).length > 32768
  ) {
    throw newErrMissingInvalidData(
      undefined,
      `field persistenceDir exceeds max size of 32768 bytes, got: ${new TextEncoder().encode(m.persistenceDir).length}`,
    );
  }
}
