/** * Applies default values to BootstrapConfig fields that are at their zero value. */
export function bootstrapConfigDefaults(m: BootstrapConfig): void {
  if (m.partitionCount === 0) {
    m.partitionCount = DEFAULT_PARTITION_COUNT;
  }
  if (m.persistenceDir === "") {
    m.persistenceDir = DEFAULT_PERSISTENCE_DIR;
  }
  if (m.raftPort === 0) {
    m.raftPort = DEFAULT_RAFT_PORT;
  }
  if (m.network) {
    networkConfigDefaults(m.network);
  }
  if (m.cpSubsystem) {
    cPSubsystemConfigDefaults(m.cpSubsystem);
  }
}

// ============================================================
// Type Defaults
// ============================================================
/** * Applies default values to NetworkConfig fields that are at their zero value. */
export function networkConfigDefaults(m: NetworkConfig): void {
  if (m.connectTimeoutSeconds === 0n) {
    m.connectTimeoutSeconds = DEFAULT_CONNECT_TIMEOUT_SECONDS;
  }
  if (m.heartbeatIntervalSeconds === 0n) {
    m.heartbeatIntervalSeconds = DEFAULT_HEARTBEAT_INTERVAL_SECONDS;
  }
  if (m.heartbeatTimeoutSeconds === 0n) {
    m.heartbeatTimeoutSeconds = DEFAULT_HEARTBEAT_TIMEOUT_SECONDS;
  }
}

// ============================================================
// Type Defaults
// ============================================================
/** * Applies default values to CPSubsystemConfig fields that are at their zero value. */
export function cPSubsystemConfigDefaults(m: CPSubsystemConfig): void {
  if (m.cpMemberCount === 0) {
    m.cpMemberCount = DEFAULT_CP_MEMBER_COUNT;
  }
  if (m.sessionTimeoutSeconds === 0n) {
    m.sessionTimeoutSeconds = DEFAULT_SESSION_TIMEOUT_SECONDS;
  }
  if (m.sessionHeartbeatIntervalSeconds === 0n) {
    m.sessionHeartbeatIntervalSeconds =
      DEFAULT_SESSION_HEARTBEAT_INTERVAL_SECONDS;
  }
  if (m.missingCpMemberAutoRemovalSeconds === 0n) {
    m.missingCpMemberAutoRemovalSeconds =
      DEFAULT_MISSING_CP_MEMBER_AUTO_REMOVAL_SECONDS;
  }
}

// ============================================================
// Type Defaults
// ============================================================
/** * Applies default values to RateLimitConfig fields that are at their zero value. */
export function rateLimitConfigDefaults(m: RateLimitConfig): void {
  if (m.pollingRate === 0) {
    m.pollingRate = DEFAULT_POLLING_RATE;
  }
  if (m.unaryRate === 0) {
    m.unaryRate = DEFAULT_UNARY_RATE;
  }
}

// ============================================================
// Type Defaults
// ============================================================
/** * Applies default values to SecurityConfig fields that are at their zero value. */
export function securityConfigDefaults(m: SecurityConfig): void {
  if (m.audience === "") {
    m.audience = DEFAULT_AUDIENCE;
  }
  if (m.tokenTtlSeconds === 0n) {
    m.tokenTtlSeconds = DEFAULT_TOKEN_TTL_SECONDS;
  }
}

// ============================================================
// Type Defaults
// ============================================================
/** * Applies default values to TokenExchangerConfig fields that are at their zero value. */
export function tokenExchangerConfigDefaults(m: TokenExchangerConfig): void {
  if (m.refreshAudience === "") {
    m.refreshAudience = DEFAULT_REFRESH_AUDIENCE;
  }
  if (m.keyRotationIntervalSeconds === 0n) {
    m.keyRotationIntervalSeconds = DEFAULT_KEY_ROTATION_INTERVAL_SECONDS;
  }
  if (m.defaultTokenExpirySeconds === 0n) {
    m.defaultTokenExpirySeconds = DEFAULT_DEFAULT_TOKEN_EXPIRY_SECONDS;
  }
}

// ============================================================
// Type Defaults
// ============================================================
/** * Applies default values to Config fields that are at their zero value. */
export function configDefaults(m: Config): void {
  if (m.rateLimit) {
    rateLimitConfigDefaults(m.rateLimit);
  }
  if (m.security) {
    securityConfigDefaults(m.security);
  }
  if (!m.tokenExchanger) {
    m.tokenExchanger = TokenExchangerConfig.create();
  }
  tokenExchangerConfigDefaults(m.tokenExchanger);
}

// ============================================================
// Type Defaults
// ============================================================
/** * Applies default values to ClusterState fields that are at their zero value. */
export function clusterStateDefaults(m: ClusterState): void {
  if (m.bootstrapConfig) {
    bootstrapConfigDefaults(m.bootstrapConfig);
  }
  if (m.frontendConfig) {
    configDefaults(m.frontendConfig);
  }
}
// ============================================================
// Type Undefaults
// ============================================================
/** Resets BootstrapConfig fields that match defaults back to zero for minimal persistence. */
export function bootstrapConfigUndefaults(m: BootstrapConfig): void {
  if (m.partitionCount === DEFAULT_PARTITION_COUNT) {
    m.partitionCount = 0;
  }
  if (m.persistenceDir === DEFAULT_PERSISTENCE_DIR) {
    m.persistenceDir = "";
  }
  if (m.raftPort === DEFAULT_RAFT_PORT) {
    m.raftPort = 0;
  }
  if (m.network) {
    networkConfigUndefaults(m.network);
  }
  if (m.cpSubsystem) {
    cPSubsystemConfigUndefaults(m.cpSubsystem);
  }
}
// ============================================================
// Type Undefaults
// ============================================================
/** Resets NetworkConfig fields that match defaults back to zero for minimal persistence. */
export function networkConfigUndefaults(m: NetworkConfig): void {
  if (m.connectTimeoutSeconds === BigInt(DEFAULT_CONNECT_TIMEOUT_SECONDS)) {
    m.connectTimeoutSeconds = 0n;
  }
  if (
    m.heartbeatIntervalSeconds === BigInt(DEFAULT_HEARTBEAT_INTERVAL_SECONDS)
  ) {
    m.heartbeatIntervalSeconds = 0n;
  }
  if (m.heartbeatTimeoutSeconds === BigInt(DEFAULT_HEARTBEAT_TIMEOUT_SECONDS)) {
    m.heartbeatTimeoutSeconds = 0n;
  }
}
