/** Fills zero-valued fields in dst from src. dst takes precedence. */
export function mergeBootstrapConfig(
  dst: BootstrapConfig,
  src: BootstrapConfig,
): void {
  if (dst.clusterName === "") {
    dst.clusterName = src.clusterName;
  }
  if (!dst.listener && src.listener) {
    dst.listener = src.listener;
  }
  if (dst.members.length === 0) {
    dst.members = src.members;
  }
  if (dst.nodeCount === 0) {
    dst.nodeCount = src.nodeCount;
  }
  if (dst.secret === "") {
    dst.secret = src.secret;
  }
  if (dst.partitionCount === 0) {
    dst.partitionCount = src.partitionCount;
  }
  if (!dst.network && src.network) {
    dst.network = src.network;
  } else if (dst.network && src.network) {
    mergeNetworkConfig(dst.network, src.network);
  }
  if (!dst.logger && src.logger) {
    dst.logger = src.logger;
  }
  if (dst.enableMetrics === false) {
    dst.enableMetrics = src.enableMetrics;
  }
  if (dst.enableTracing === false) {
    dst.enableTracing = src.enableTracing;
  }
  if (!dst.cpSubsystem && src.cpSubsystem) {
    dst.cpSubsystem = src.cpSubsystem;
  } else if (dst.cpSubsystem && src.cpSubsystem) {
    mergeCPSubsystemConfig(dst.cpSubsystem, src.cpSubsystem);
  }
  if (dst.persistenceDir === "") {
    dst.persistenceDir = src.persistenceDir;
  }
  if (dst.persistenceFormat === 0) {
    dst.persistenceFormat = src.persistenceFormat;
  }
  if (dst.loaderCa.length === 0) {
    dst.loaderCa = src.loaderCa;
  }
  if (!dst.tls && src.tls) {
    dst.tls = src.tls;
  }
  if (dst.raftPort === 0) {
    dst.raftPort = src.raftPort;
  }
  if (dst.config.case === undefined && src.config.case !== undefined) {
    dst.config = src.config;
  }
}
